'use strict';
// Audio fades share the same envelope in timeline preview and exported mixes.
function fadeDurations(c){let a=clamp(c.fadeIn||0,0,c.duration),b=clamp(c.fadeOut||0,0,c.duration);if(a+b>c.duration){const ratio=c.duration/(a+b);a*=ratio;b*=ratio}return{in:a,out:b}}
function envelopeAt(c,t){const f=fadeDurations(c);return c.volume*(typeof normalizationGain==='function'?normalizationGain(c):1)*Math.max(0,Math.min(1,f.in?t/f.in:1,f.out?(c.duration-t)/f.out:1))}
function scheduleEnvelope(param,c,when,skip,length){const f=fadeDurations(c);param.setValueAtTime(envelopeAt(c,skip),when);for(const t of [...new Set([f.in,c.duration-f.out,c.duration])].sort((a,b)=>a-b)){if(t>skip&&t<skip+length)param.linearRampToValueAtTime(envelopeAt(c,t),when+t-skip)}param.linearRampToValueAtTime(envelopeAt(c,skip+length),when+length)}
function paintAudioFades(el,c,delta=0,mode=''){const f=fadeDurations(c);if(mode==='fadeIn')f.in=clamp(f.in+delta,0,c.duration-f.out);if(mode==='fadeOut')f.out=clamp(f.out-delta,0,c.duration-f.in);const duration=c.duration||1;for(const side of ['in','out']){const ramp=el.querySelector('.fade-ramp.'+side);if(ramp)ramp.style.width=(f[side]/duration*100)+'%';const handle=el.querySelector('.audio-fade.'+side);if(handle)handle.style.left=side==='in'?Math.max(5,f.in*timelineZoom)+'px':'calc(100% - '+Math.max(5,f.out*timelineZoom)+'px)';if(handle)handle.title=(side==='in'?'Fade in':'Fade out')+' · '+f[side].toFixed(2)+' s · drag to adjust'}}
function addAudioFadeHandles(el,c){for(const side of ['in','out']){const ramp=document.createElement('span');ramp.className='fade-ramp '+side;el.append(ramp);const handle=document.createElement('span');handle.className='audio-fade '+side;handle.dataset.edge=side==='in'?'fadeIn':'fadeOut';handle.setAttribute('role','slider');handle.setAttribute('aria-label',side==='in'?'Audio fade in':'Audio fade out');handle.tabIndex=0;handle.onkeydown=e=>{if(e.key!=='ArrowLeft'&&e.key!=='ArrowRight')return;e.preventDefault();e.stopPropagation();moveAudio(c,{delta:(e.key==='ArrowRight'?.1:-.1),mode:handle.dataset.edge});save();render()};el.append(handle)}paintAudioFades(el,c)}
const editAudioBeforeFades=moveAudio;
moveAudio=function(c,change){if(change.mode==='fadeIn'||change.mode==='fadeOut'){const f=fadeDurations(c);if(change.mode==='fadeIn')c.fadeIn=clamp(f.in+change.delta,0,c.duration-f.out);else c.fadeOut=clamp(f.out-change.delta,0,c.duration-f.in)}else{editAudioBeforeFades(c,change);const f=fadeDurations(c);c.fadeIn=f.in;c.fadeOut=f.out}};
const settingsBeforeFades=renderClipSettings;
renderClipSettings=function(){settingsBeforeFades();const c=tracks().find(c=>c.id===selectedAudio);if(!c)return;const f=fadeDurations(c);for(const [name,key,side] of [['Fade in','fadeIn','in'],['Fade out','fadeOut','out']]){const label=document.createElement('label');label.textContent=name;const input=document.createElement('input');input.type='number';input.min=0;input.max=c.duration;input.step=.05;input.value=+f[side].toFixed(2);input.setAttribute('aria-label',name+' seconds');input.onchange=()=>{const value=+input.value;if(!Number.isFinite(value))return;moveAudio(c,{mode:key,delta:(value-f[side])*(side==='out'?-1:1)});save();render()};label.append(input);$('clipSettings').append(label)}};
const validBeforeFades=valid;valid=function(p){return validBeforeFades(p)&&(p.audioClips||[]).every(c=>['fadeIn','fadeOut'].every(k=>c[k]===undefined||Number.isFinite(c[k])&&c[k]>=0&&c[k]<=c.duration))};
// Scene exit transitions are drawn here for both editing preview and recording.
for(const [value,text] of [['black','Fade to black'],['white','Fade to white'],['wipe','Wipe to paper']]){const option=document.createElement('option');option.value=value;option.textContent=text;$('transition').append(option)}
$('transition').parentElement.insertAdjacentHTML('afterend','<label>Transition length<input id="transitionLength" type="number" min="0.1" max="3" step="0.1" value="0.5"></label>');
$('transitionLength').onchange=e=>{stop();current().transitionDuration=clamp(+e.target.value||.5,.1,Math.min(3,current().duration));save();render()};$('transition').onchange=e=>{stop();current().transition=e.target.value;save();draw()};
function drawSceneTransition(c,s,t){if(!s.transition||s.transition==='cut')return;const length=Math.min(s.transitionDuration??.5,s.duration),f=clamp((t-s.duration+length)/length,0,1);if(!f)return;c.save();c.setTransform($('stage').width/960,0,0,$('stage').height/540,0,0);if(s.transition==='wipe')rect(c,0,0,960*f,540,s.bg);else{c.globalAlpha=f;rect(c,0,0,960,540,s.transition==='black'?'#000000':s.transition==='white'?'#ffffff':s.bg)}c.restore()}
const extrasBeforeEffects=renderExtras;renderExtras=function(){extrasBeforeEffects();$('transitionLength').value=current().transitionDuration??.5};
const drawBeforeTransitions=draw;draw=function(){drawBeforeTransitions();drawSceneTransition(ctx,current(),time)};
// Pose keyframes can be sought and moved directly inside their visual clips.
function wireKeyframeMarker(el,o,k){el.title='Keyframe · '+k.t.toFixed(2)+' s · drag to retime';el.tabIndex=0;el.setAttribute('role','slider');el.setAttribute('aria-label',o.name+' keyframe at '+k.t.toFixed(2)+' seconds');el.onpointerdown=e=>{e.stopPropagation();if(o.locked||recording)return;stop();selected=o.id;selectedAudio=null;const start=e.clientX,original=k.t;let target=original;el.setPointerCapture(e.pointerId);el.onpointermove=ev=>{target=clamp(Math.round((original+(ev.clientX-start)/timelineZoom)*30)/30,clipStart(o),clipEnd(o));el.style.left=(target-clipStart(o))*timelineZoom+'px';el.title=target.toFixed(2)+' s'};el.onpointerup=()=>{el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null;if(o.keys.some(other=>other!==k&&Math.abs(other.t-target)<.015)){target=original;toast('A keyframe already exists at that time.')}if(target!==original){k.t=target;o.keys.sort((a,b)=>a.t-b.t);save()}time=k.t;render()};el.onpointercancel=()=>render()};el.onkeydown=e=>{if(o.locked||recording)return;if(e.key==='Enter'){e.preventDefault();stop();selected=o.id;selectedAudio=null;time=k.t;render()}else if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();e.stopPropagation();const t=clamp(k.t+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?.1:1/30),clipStart(o),clipEnd(o));if(!o.keys.some(other=>other!==k&&Math.abs(other.t-t)<.015)){k.t=t;o.keys.sort((a,b)=>a.t-b.t);time=t;save();render()}}}}
const keysBeforeTimeline=renderKeys;renderKeys=function(){keysBeforeTimeline();if($('trackContent')&&typeof wireKeyframeMarker==='function')renderTimeline()};
